-- Rifts World Book 35: Megaverse in Flames, the Minion War arms race: demon bows and arrows, demon guns and demon magic artifacts (printed 125-129)
-- 20 gear rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~346-megaverse-in-flames-arms-race.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.
-- The Minion War Arms Race chapter: three Demon Bows, the plain Bone Arrowhead and
-- six Magic Bone Arrowheads (printed 125-126), two TW Iron Bolt guns and three
-- Bone Shard guns (126-127), and five Demon Magic Artifacts (127-129). Every
-- damage, cost, weight and P.P.E. figure was read off a render of its page.
-- The Demon Melee Weapons heading on printed 125 introduces the bows and arrows
-- and prints no melee weapon of its own, so there is none to add.
-- A RANGE IS STORED BY ITS LOW END; cost_note gives the whole range. The Demon
-- Bows' 4D6+34 M.D.C. is rolled, so mdc is left empty and each says so.
-- Arrows are category gear, as the catalog's other arrowhead rows are.
-- Not the same item, left alone: demon-or-deevil-blood and demon-or-deevil-bones
-- (Palladium Fantasy).

INSERT OR IGNORE INTO gear (slug, name, system, category, weight_lbs, cost, cost_note, damage, is_mega_damage, range, payload, rate_of_fire, ar, sdc, mdc, description, source_book, vehicle_slug) VALUES
  ('bow-of-demons', 'Bow of Demons', 'rifts', 'weapon', NULL, 60000, '60,000-100,000 credits as a one-off item at a market like the Splynn D-Market.', '4D6 M.D. with a standard bone arrowhead', 1, '1,200 feet (366 m)', NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Bows, designed by the demon weaponsmith Rat_Bastard. A plain, unenchanted demon longbow of curved bone, strung with sinew or braided hair from a supernatural creature. Like every Demon Bow it takes a Supernatural P.S. of 21, or its equal, to draw, and has 4D6+34 M.D.C.; that figure is rolled, so the mdc column is left empty. Issued only to small elite units of demon archers who know how to use a bow.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('bow-of-defiling', 'Bow of Defiling', 'rifts', 'weapon', NULL, 250000, '250,000-450,000 credits as a one-off item at a market like the Splynn D-Market.', '4D6 M.D. with a standard bone arrowhead, plus the spell''s effect when an arrow is enchanted', 1, '1,400 feet (427 m)', NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Bows, designed by the demon weaponsmith Rat_Bastard. A demon longbow cut from a curved rib, strung with sinew or braided hair from a supernatural creature. +1 to strike. Its archer may lay Fear, Summon and Control Rodents, or Spoil (Water/Food) on an arrow, each up to three times a day, at 5th level potency. Like every Demon Bow it takes a Supernatural P.S. of 21, or its equal, to draw, and has 4D6+34 M.D.C.; that figure is rolled, so the mdc column is left empty.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('bow-of-pain', 'Bow of Pain', 'rifts', 'weapon', NULL, 500000, '500,000-750,000 credits.', '4D6 M.D. with standard bone arrowheads, plus the spell''s damage or effect when an arrow is enchanted', 1, '1,800 feet (549 m)', NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Bows, designed by the demon weaponsmith Rat_Bastard. A demonic compound bow built from one big rib or several bone pieces, with small pulleys for extra draw, strung with sinew or braided hair. Its archer may lay Energy Bolt (4D6+12 S.D.C.), Fire Ball (3D6+3 M.D.), Agony or Electric Arc (2D6 M.D.) on an arrow, each up to three times a day, at 5th level potency. Like every Demon Bow it takes a Supernatural P.S. of 21, or its equal, to draw, and has 4D6+34 M.D.C.; that figure is rolled, so the mdc column is left empty.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('bone-arrowhead', 'Bone Arrowhead', 'rifts', 'gear', NULL, 50, '50-100 credits each, in mortal realms where they are a rarity; mass produced among demons.', '4D6 M.D.', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Arrows. The ordinary demon arrow: a head of bone taken from a creature of magic or a supernatural being, on a plain wooden or bone shaft. Fits every Demon Bow. Too big for a human-sized bow, though a giant-sized bow could loose it.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('fire-blast-arrowhead', 'Fire Blast Arrowhead', 'rifts', 'gear', NULL, 10000, '10,000 credits per arrow.', 'As the arrow (4D6 M.D. from a Demon Bow) plus 3D6 M.D. magical fire', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. An enchanted demon bone arrow that bursts into flame when it hits, adding magical fire damage to the arrow''s own.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('electric-shock-arrowhead', 'Electric Shock Arrowhead', 'rifts', 'gear', NULL, 12000, '12,000 credits per arrow.', 'As the arrow (4D6 M.D. from a Demon Bow) plus 3D6 M.D. magical electricity', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. An enchanted demon bone arrow that releases a burst of electricity on impact, adding magical electrical damage to the arrow''s own.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('ice-blast-arrowhead', 'Ice Blast Arrowhead', 'rifts', 'gear', NULL, 12000, '12,000 credits per arrow.', 'As the arrow (4D6 M.D. from a Demon Bow) plus 3D6 M.D. magical cold', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. An enchanted demon bone arrow that lets off a freezing blast where it strikes, adding magical cold damage to the arrow''s own.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('globe-of-daylight-arrowhead', 'Globe of Daylight Arrowhead', 'rifts', 'gear', NULL, 7500, '7,500 credits per arrow.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. A silver-tipped wooden arrow carrying a globe of daylight that lasts six minutes: a flare, or a weapon against things that sunlight or wood can hurt, vampires above all. Damage is the arrow''s own plus that effect.', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('splinter-arrow', 'Splinter Arrow', 'rifts', 'gear', NULL, 2000, '2,000 credits each.', '1D4 M.D. to everything within an 8 ft (2.4 m) swath around the target', 1, '1,000 feet (305 m) at most', NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. A thick, heavy arrow made all of bone that bursts into shards, showering bone shrapnel on the target and everyone and everything close around it. Its range is capped at 1,000 feet (305 m).', 'Rifts World Book 35: Megaverse in Flames p.125', NULL),
  ('sudden-illness-arrow', 'Sudden Illness Arrow', 'rifts', 'gear', NULL, 20000, '20,000 credits per arrow.', '2D6 direct to Hit Points against a mortal/S.D.C. being, 2D6 M.D. against a Mega-Damage being, plus sickness unless the target saves on 13 or better', 1, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Magic Bone Arrowheads. An arrow of rotten, stinking bone that is always trailed by flies. A living target that fails a save of 13 or better is struck at once by violent nausea, fever and dizziness for 1D4+2 minutes: -2 melee attacks a round, combat bonuses and Spd halved, and -10% to skills. The book says the sickness reaches targets in non-environmental armor.', 'Rifts World Book 35: Megaverse in Flames p.125-126', NULL),
  ('iron-eye-deevil-slayer-pistol', 'Iron Eye Deevil Slayer Pistol', 'rifts', 'weapon', 6, 45000, '45,000 credits, were it ever offered on a market.', '2D6 M.D., doubled against iron-vulnerable Deevils', 1, '300 feet (91.4 m)', 'No power source of its own: the shooter spends 10 P.P.E. to create and fire each iron needle', 'Single shot; one melee attack per blast', NULL, NULL, NULL, 'Minion War arms race, TW Iron Bolt weapons. The smallest Techno-Wizard Iron Bolt gun, a demon arm made with Soulmancy that looks like a handsome old flintlock pistol and reeks of supernatural evil. It fires a conjured iron needle about 4 inches (10 cm) long, made to kill Deevils. The Deevils sabotaged most of the plants that build these, so demons are short of them.', 'Rifts World Book 35: Megaverse in Flames p.126', NULL),
  ('iron-bolt-deevil-slayer-rifle', 'Iron Bolt Deevil Slayer Rifle', 'rifts', 'weapon', 15, 100000, '100,000 credits, were it ever offered on a market.', '4D6 M.D., doubled against iron-vulnerable Deevils', 1, '1,400 feet (426.7 m)', 'No power source of its own: the shooter spends 20 P.P.E. to create and fire each iron round', 'Single shot only', NULL, NULL, NULL, 'Minion War arms race, TW Iron Bolt weapons. The long-gun of the Techno-Wizard Iron Bolt line, shaped like a flintlock rifle and built with Soulmancy. A telekinetic enchantment hurls a conjured iron shaft 12 inches (0.3 m) long, out-ranging and out-hitting the pistol. The Deevils sabotaged most of the plants that build these, so demons are short of them.', 'Rifts World Book 35: Megaverse in Flames p.126', NULL),
  ('bone-gutter-pistol', 'Bone Gutter Pistol', 'rifts', 'weapon', 8, 20000, '20,000-30,000 credits were it on the market, to a very narrow clientele.', '3D6+3 M.D. a burst', 1, '400 feet (122 m)', 'Varies: an arm yields 1D4+2 bursts and a leg or similar bones 1D6+3, then a new bone is needed', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Minion War arms race, Bone Shard (Splinter) weapons, made by Hell Lord Heart Ripper''s alchemists from Soulmancy, Techno-Wizardry and salvaged guns. The smallest of the line, a sub-machinegun in effect: one-handed for a demon-sized wielder, two-handed for anyone else. No magic makes its ammunition. Bones, flesh and all, are pushed into a skull-like mouth at the rear, ground into shards and blasted out of a wide muzzle with a spray of gore.', 'Rifts World Book 35: Megaverse in Flames p.126-127', NULL),
  ('bone-crusher-shard-rifle', 'Bone Crusher Shard Rifle', 'rifts', 'weapon', 20, 40000, '40,000-50,000 credits were it on the market, to a very narrow clientele.', '1D4x10+4 M.D. a burst', 1, '1,800 feet (548.6 m)', 'Varies: usually 2D4+4 bursts with a bone in each opening; half that with only one fed', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Minion War arms race, Bone Shard (Splinter) weapons, made by Hell Lord Heart Ripper''s alchemists from Soulmancy, Techno-Wizardry and salvaged guns. A long-barrelled rifle whose rear is a maw with two openings, so two bones jut back from it in a sideways V. The noise of the grinding bones adds +1 to the wielder''s Horror Factor. Ammunition is any bone fed in, ground into shards and fired from a wide muzzle.', 'Rifts World Book 35: Megaverse in Flames p.127', NULL),
  ('bone-grinder-shard-cannon', 'Bone Grinder Shard Cannon', 'rifts', 'weapon', 100, 70000, '70,000-80,000 credits were it on the market, to a very narrow clientele.', '2D4x10+6 M.D. a burst', 1, '1,500 feet (457.2 m)', 'Varies: 2D4+4 bursts from a cluster of bones fed into its single large maw at the back (top)', 'Each burst counts as one melee attack', NULL, NULL, NULL, 'Minion War arms race, Bone Shard (Splinter) weapons, made by Hell Lord Heart Ripper''s alchemists from Soulmancy, Techno-Wizardry and salvaged guns. The heaviest of the line, with three barrels; even most demons struggle to handle it, so it goes mostly to officers, heavy weapons specialists and demon special forces. Ammunition is any bone fed in, ground into shards and fired from a wide muzzle.', 'Rifts World Book 35: Megaverse in Flames p.127', NULL),
  ('beast-charm', 'Beast Charm', 'rifts', 'gear', NULL, 2000000, '2-4 million credits, open market.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Magic Artifacts. A brooch-sized charm, often carved as a bull or a Beast''s face, cut from a Deevil Beast''s forehead horn (a full horn makes up to 10) and quenched in the blood of a Beast after firing in a magical furnace. +1 to save vs magic that a Beast casts. For 50 P.P.E., twice a day, the owner can take the form of a great demonic bull, as a Deevil Beast does, for one hour: +40 M.D.C. (possibly a mortal''s only M.D.C.), half damage from fire and cold, and the aura and smell of a Beast, enough to fool some Host and Deevils. All the owner''s other abilities are unchanged.', 'Rifts World Book 35: Megaverse in Flames p.127-128', NULL),
  ('devilkin-amulet', 'Devilkin Amulet', 'rifts', 'gear', NULL, 3000000, '3-5 million credits, open market.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Magic Artifacts. A Devilkin''s skull, shrunk to golf-ball size by Soulmancy and further enchantments, apparently gilded and marked on the brow with a strange magic symbol; the Devilkin is said to live through most of the process. +2 to save vs magic that a Devilkin or Deevil casts. For 30 P.P.E. the bearer can become a Devilkin or an unremarkable human for up to eight hours, after which it must recharge for 24 hours. In that shape: +10 M.D.C. (possibly a mortal''s only M.D.C.), half damage from fire and cold, and the aura and smell of whichever form was taken. It works only worn or carried on the body (neck, upper arm or belt are usual, under clothing is fine), never from inside a bag or pouch.', 'Rifts World Book 35: Megaverse in Flames p.128', NULL),
  ('gorgon-monocle', 'Gorgon Monocle', 'rifts', 'gear', NULL, 1000000, '1-5 million credits; extremely rare.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Magic Artifacts. A monocle of part of a Gorgon''s skull with a lens made from the Gorgon''s own eye, usually worn with a patch over the other eye. Gorgons are proof against their own gaze, so the lens shields the wearer from petrification, letting him face a Gorgon alone. The price is near-blindness on one side: -3 to all combat bonuses (initiative, strike, parry, dodge and so on), -3 to Perception Rolls and -1 attack per melee. Knock the monocle off and the protection goes with it. Few exist, since the Gorgon must die in Dyval or at the lip of a Hell Pit into it for its eyes to be taken; they go to small anti-Gorgon teams such as the Brass Guard II.', 'Rifts World Book 35: Megaverse in Flames p.128', NULL),
  ('gorgon-poison', 'Gorgon Poison', 'rifts', 'gear', NULL, 50000, '50,000-100,000 credits per ounce (two doses).', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Magic Artifacts. A crystalline powder of Gorgon blood, drawn again and again from captive Gorgons and dried with magical mixtures; it can be slipped into most food and drink and harms supernatural beings and creatures of magic. A supernatural victim must save vs magic poison on 15 or better, a mortal on 16 or better, using whichever of save vs magic or save vs poison is higher. A failed save turns the victim to stone for a time rolled on percentile dice: 1D6 minutes on 01-20, 1D6 hours on 21-40, 1D6 days on 41-60, 1D6 years on 61-80, permanently on 81-00. Only magic such as Stone to Flesh undoes it; Splugorth Bio-Wizards reputedly own a bath that works 01-90%, and a Gorgon or Medusa can reverse it at a price. A successful save still does 6D6 M.D. to a supernatural being (a mortal takes 1D4x10 S.D.C.) and brings 1D4 hours of cold grey stiffness: -1 attack per melee, -1 to all combat bonuses, -10% Spd.', 'Rifts World Book 35: Megaverse in Flames p.129', NULL),
  ('omni-eyes', 'Omni Eyes', 'rifts', 'gear', NULL, 3000000, '3-12 million credits; very rare.', NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 'Minion War arms race, Demon Magic Artifacts. A charm made from a Deevil Horror''s eye, cut out with a cold iron blade, kept alive by Soulmancy, shrunk in a broth to ping-pong-ball size, dried and sealed in glass. Its wearer sees all the way around him, so he cannot be surprised from the sides or rear, sees the invisible, has perfect 20/20 sight and Nightvision to 120 feet (36.6 m), and gains +1 to dodge, +1 on initiative and +2 to Perception Rolls. All of it is constant and automatic.', 'Rifts World Book 35: Megaverse in Flames p.129', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 20 gear rows are in' AS assertion, count(*) AS got, 20 AS want
  FROM gear WHERE slug IN ('bow-of-demons', 'bow-of-defiling', 'bow-of-pain', 'bone-arrowhead', 'fire-blast-arrowhead', 'electric-shock-arrowhead', 'ice-blast-arrowhead', 'globe-of-daylight-arrowhead', 'splinter-arrow', 'sudden-illness-arrow', 'iron-eye-deevil-slayer-pistol', 'iron-bolt-deevil-slayer-rifle', 'bone-gutter-pistol', 'bone-crusher-shard-rifle', 'bone-grinder-shard-cannon', 'beast-charm', 'devilkin-amulet', 'gorgon-monocle', 'gorgon-poison', 'omni-eyes') AND source_book IS NOT NULL;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~346-megaverse-in-flames-arms-race.sql');
